{"content":"package ledger

import (
	"context"
	"sync"
	"testing"
)

func TestTransferOne(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	got, err := book.Transfer(context.Background(), "tx-1", "a", "b", 3)
	if err != nil || got.FromBalance != 7 || got.ToBalance != 3 { t.Fatalf("receipt=%+v error=%v", got, err) }
}

func TestTransferValidation(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 5})
	if _, err := book.Transfer(context.Background(), "", "a", "b", 1); err != ErrInvalid { t.Errorf("empty id: %v", err) }
	if _, err := book.Transfer(context.Background(), "x", "a", "a", 1); err != ErrInvalid { t.Errorf("same account: %v", err) }
	if _, err := book.Transfer(context.Background(), "x", "a", "missing", 1); err != ErrMissingAccount { t.Errorf("missing to: %v", err) }
	if _, err := book.Transfer(context.Background(), "x", "missing", "b", 1); err != ErrMissingAccount { t.Errorf("missing from: %v", err) }
	if _, err := book.Transfer(context.Background(), "x", "a", "b", 0); err != ErrInvalid { t.Errorf("zero amount: %v", err) }
	if _, err := book.Transfer(context.Background(), "x", "a", "b", -1); err != ErrInvalid { t.Errorf("negative amount: %v", err) }
	if bal, _ := book.Balance("a"); bal != 10 { t.Errorf("balance mutated: %d", bal) }
}

func TestTransferInsufficientFunds(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 5, "b": 0})
	if _, err := book.Transfer(context.Background(), "tx", "a", "b", 6); err != ErrInsufficientFunds { t.Fatalf("err=%v", err) }
	if bal, _ := book.Balance("a"); bal != 5 { t.Errorf("from mutated: %d", bal) }
	if bal, _ := book.Balance("b"); bal != 0 { t.Errorf("to mutated: %d", bal) }
}

func TestTransferRetryAndConflict(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	r1, err := book.Transfer(context.Background(), "tx", "a", "b", 3)
	if err != nil { t.Fatal(err) }
	r2, err := book.Transfer(context.Background(), "tx", "a", "b", 3)
	if err != nil { t.Fatal(err) }
	if r1 != r2 { t.Errorf("retry receipt mismatch: %+v vs %+v", r1, r2) }
	if bal, _ := book.Balance("a"); bal != 7 { t.Errorf("double transfer: %d", bal) }
	if _, err := book.Transfer(context.Background(), "tx", "a", "b", 4); err != ErrConflict { t.Errorf("conflict: %v", err) }
	if _, err := book.Transfer(context.Background(), "tx", "b", "a", 3); err != ErrConflict { t.Errorf("conflict2: %v", err) }
}

func TestTransferCancelledContext(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 10, "b": 0})
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := book.Transfer(ctx, "tx", "a", "b", 3); err == nil { t.Fatal("expected error") }
	if bal, _ := book.Balance("a"); bal != 10 { t.Errorf("mutated: %d", bal) }
}

func TestTransferConcurrent(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 1000, "b": 0})
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			id := "tx-" + string(rune('a'+i%26)) + "-" + string(rune('0'+i/26))
			_, _ = book.Transfer(context.Background(), id, "a", "b", 1)
		}(i)
	}
	wg.Wait()
	// Each unique ID transfers exactly once; total moved equals number of unique IDs that succeeded.
	a, _ := book.Balance("a")
	b, _ := book.Balance("b")
	if a+b != 1000 { t.Errorf("total changed: a=%d b=%d", a, b) }
	if b != 1000-a { t.Errorf("inconsistent: a=%d b=%d", a, b) }
}

func TestTransferConcurrentSameID(t *testing.T) {
	book := NewLedger(map[string]int64{"a": 100, "b": 0})
	var wg sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, _ = book.Transfer(context.Background(), "same", "a", "b", 5)
		}()
	}
	wg.Wait()
	if bal, _ := book.Balance("a"); bal != 95 { t.Errorf("a=%d", bal) }
	if bal, _ := book.Balance("b"); bal != 5 { t.Errorf("b=%d", bal) }
}
